# Refined rotation functions
def rotate_90_cw(grid):
    """Rotate 90 degrees clockwise"""
    return [[grid[j][i] for j in range(len(grid))] for i in range(len(grid[0])-1, -1, -1)]

def rotate_180(grid):
    """Rotate 180 degrees"""
    return [row[::-1] for row in grid[::-1]]

def rotate_90_ccw(grid):
    """Rotate 90 degrees counter-clockwise (or 270 CW)"""
    return [[grid[j][i] for j in range(len(grid)-1, -1, -1)] for i in range(len(grid[0]))]

def rotate_270_cw(grid):
    """Same as 90 CCW"""
    return rotate_90_ccw(grid)

def hflip(grid):
    """Horizontal flip (mirror across vertical axis)"""
    return [row[::-1] for row in grid]

def vflip(grid):
    """Vertical flip (mirror across horizontal axis)"""
    return grid[::-1]

def transpose(grid):
    """Transpose (swap rows and columns)"""
    return [[grid[j][i] for j in range(len(grid))] for i in range(len(grid[0]))]

def anti_diagonal(grid):
    """Reflect across anti-diagonal (top-right to bottom-left)"""
    n = len(grid)
    return [[grid[n-1-j][n-1-i] for j in range(n)] for i in range(n)]

def main_diagonal(grid):
    """Reflect across main diagonal (top-left to bottom-right) = transpose"""
    return [[grid[j][i] for j in range(len(grid))] for i in range(len(grid[0]))]

